    if by_currency:
        entries = parse_csv(text)
        return json.dumps({'totals': {c: format(v, '.2f') for c, v in totals_by_currency(entries, start=start, end=end).items()}}, sort_keys=True)
    return json.dumps({'total':format(total(parse_csv(text)),'.2f')},sort_keys=True)

